-- Real DVSA data: 2024-25 (Apr 2024 - Mar 2025), Open Government Licence v3.0
-- Sources: DRT122A (overall), DRT122C (first-attempt), DRT122D (by age 17-25),
-- merged by test centre name. 318 centres total (union of all three files).
-- Excludes LGV/HGV test centres and closed ('Z'-prefixed) centres.

-- Schema migration
alter table pass_rate_stats alter column tests_conducted drop not null;
alter table pass_rate_stats alter column tests_passed drop not null;
alter table pass_rate_stats add column if not exists first_attempt_tests integer check (first_attempt_tests >= 0);
alter table pass_rate_stats add column if not exists first_attempt_passes integer check (first_attempt_passes >= 0);
alter table pass_rate_stats add column if not exists first_attempt_zero_fault_passes integer check (first_attempt_zero_fault_passes >= 0);

create table if not exists age_pass_rates (
  id uuid primary key default gen_random_uuid(),
  centre_id uuid not null references test_centres(id) on delete cascade,
  period_label text not null,
  age integer not null check (age between 17 and 25),
  tests_conducted integer not null check (tests_conducted >= 0),
  tests_passed integer not null check (tests_passed >= 0),
  unique (centre_id, period_label, age)
);
alter table age_pass_rates enable row level security;
drop policy if exists "public read age_pass_rates" on age_pass_rates;
create policy "public read age_pass_rates" on age_pass_rates for select using (true);
create index if not exists idx_age_pass_rates_centre on age_pass_rates(centre_id);

delete from age_pass_rates;
delete from pass_rate_stats;
delete from reviews;
delete from test_centres;

